def est_premier(n: int) -> bool:
    """Retourne True si n est un nombre premier, sinon False."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    # Vérifier les diviseurs impairs jusqu'à sqrt(n)
    limite = int(n ** 0.5) + 1
    for diviseur in range(3, limite, 2):
        if n % diviseur == 0:
            return False
    return True
```
